private fun toSdkAttributeValue(v: Union10<AttributeValue.S, AttributeValue.N, AttributeValue.B, AttributeValue.Ss, AttributeValue.Ns, AttributeValue.Bs, AttributeValue.M, AttributeValue.L, AttributeValue.Bool, AttributeValue.Null>): aws.sdk.kotlin.services.dynamodb.model.AttributeValue = when (v) {
    is Union10.U1<*, *, *, *, *, *, *, *, *, *> -> { val x = v.value as AttributeValue.S; aws.sdk.kotlin.services.dynamodb.model.AttributeValue.S(x.value) }
    is Union10.U2<*, *, *, *, *, *, *, *, *, *> -> { val x = v.value as AttributeValue.N; aws.sdk.kotlin.services.dynamodb.model.AttributeValue.N(x.value) }
    is Union10.U3<*, *, *, *, *, *, *, *, *, *> -> { val x = v.value as AttributeValue.B; aws.sdk.kotlin.services.dynamodb.model.AttributeValue.B(x.value.toByteArray()) }
    is Union10.U4<*, *, *, *, *, *, *, *, *, *> -> { val x = v.value as AttributeValue.Ss; aws.sdk.kotlin.services.dynamodb.model.AttributeValue.Ss(x.value) }
    is Union10.U5<*, *, *, *, *, *, *, *, *, *> -> { val x = v.value as AttributeValue.Ns; aws.sdk.kotlin.services.dynamodb.model.AttributeValue.Ns(x.value) }
    is Union10.U6<*, *, *, *, *, *, *, *, *, *> -> { val x = v.value as AttributeValue.Bs; aws.sdk.kotlin.services.dynamodb.model.AttributeValue.Bs(x.value.map { it.toByteArray() }) }
    is Union10.U7<*, *, *, *, *, *, *, *, *, *> -> { val x = v.value as AttributeValue.M; aws.sdk.kotlin.services.dynamodb.model.AttributeValue.M(x.value.associate { (k, e) -> k to toSdkAttributeValue(e) }) }
    is Union10.U8<*, *, *, *, *, *, *, *, *, *> -> { val x = v.value as AttributeValue.L; aws.sdk.kotlin.services.dynamodb.model.AttributeValue.L(x.value.map { toSdkAttributeValue(it) }) }
    is Union10.U9<*, *, *, *, *, *, *, *, *, *> -> { val x = v.value as AttributeValue.Bool; aws.sdk.kotlin.services.dynamodb.model.AttributeValue.Bool(x.value) }
    is Union10.U10<*, *, *, *, *, *, *, *, *, *> -> { val x = v.value as AttributeValue.Null; aws.sdk.kotlin.services.dynamodb.model.AttributeValue.Null(x.value) }
}

private fun fromSdkAttributeValue(v: aws.sdk.kotlin.services.dynamodb.model.AttributeValue): Union10<AttributeValue.S, AttributeValue.N, AttributeValue.B, AttributeValue.Ss, AttributeValue.Ns, AttributeValue.Bs, AttributeValue.M, AttributeValue.L, AttributeValue.Bool, AttributeValue.Null> = when (v) {
    is aws.sdk.kotlin.services.dynamodb.model.AttributeValue.S -> Union10.U1(AttributeValue.S(value = v.value))
    is aws.sdk.kotlin.services.dynamodb.model.AttributeValue.N -> Union10.U2(AttributeValue.N(value = v.value))
    is aws.sdk.kotlin.services.dynamodb.model.AttributeValue.B -> Union10.U3(AttributeValue.B(value = salvo.SalvoBytes(v.value)))
    is aws.sdk.kotlin.services.dynamodb.model.AttributeValue.Ss -> Union10.U4(AttributeValue.Ss(value = v.value))
    is aws.sdk.kotlin.services.dynamodb.model.AttributeValue.Ns -> Union10.U5(AttributeValue.Ns(value = v.value))
    is aws.sdk.kotlin.services.dynamodb.model.AttributeValue.Bs -> Union10.U6(AttributeValue.Bs(value = v.value.map { salvo.SalvoBytes(it) }))
    is aws.sdk.kotlin.services.dynamodb.model.AttributeValue.M -> Union10.U7(AttributeValue.M(value = salvo.platform.std.core.map.canonicalMap(v.value.entries.sortedBy { it.key }.map { (k, e) -> k to fromSdkAttributeValue(e) })))
    is aws.sdk.kotlin.services.dynamodb.model.AttributeValue.L -> Union10.U8(AttributeValue.L(value = v.value.map { fromSdkAttributeValue(it) }))
    is aws.sdk.kotlin.services.dynamodb.model.AttributeValue.Bool -> Union10.U9(AttributeValue.Bool(value = v.value))
    is aws.sdk.kotlin.services.dynamodb.model.AttributeValue.Null -> Union10.U10(AttributeValue.Null(value = v.value))
    else -> error("DynamoDB sent an attribute value this client does not map: $v")
}

/** A code as the model names it (see the Rust glue's `salvo_code`). */
private fun salvoCode(code: String): String = when (val c = code.substringAfterLast('#')) {
    "Throttling" -> "ThrottlingException"
    else -> c
}

private fun salvoFailure(e: aws.smithy.kotlin.runtime.ServiceException): DdbError {
    val meta = e.sdkErrorMetadata
    val response = meta.protocolResponse as? aws.smithy.kotlin.runtime.http.response.HttpResponse
    return DdbError(
        code = salvoCode(meta.errorCode ?: "Unknown"),
        message = meta.errorMessage ?: "",
        status = response?.status?.value ?: 0,
        requestId = meta.requestId,
    )
}

/** A Smithy timestamp as a `time.Instant`: nanoseconds since the epoch. */
private fun salvoInstant(t: aws.smithy.kotlin.runtime.time.Instant): salvo.std.time.Instant =
    salvo.std.time.Instant(nanos = t.epochSeconds * 1_000_000_000L + t.nanosecondsOfSecond)

/** A `time.Instant` as a Smithy timestamp. */
private fun salvoDateTime(at: salvo.std.time.Instant): aws.smithy.kotlin.runtime.time.Instant =
    aws.smithy.kotlin.runtime.time.Instant.fromEpochSeconds(
        Math.floorDiv(at.nanos, 1_000_000_000L),
        Math.floorMod(at.nanos, 1_000_000_000L).toInt(),
    )

private fun salvoAwsError(e: Throwable): AwsError {
    val code = (e as? aws.smithy.kotlin.runtime.ServiceException)?.sdkErrorMetadata?.errorCode
        ?: e::class.simpleName ?: "Exception"
    return AwsError(code = code, message = e.message ?: e.toString())
}
